-- Backfill: one practitioner per business that has switched appointments on, named after the business (the
-- clinic renames it to the real doctor later), using the clinic's own opening hours (uses_clinic_hours defaults to
-- true). Application code generates uuidv7 ids for new rows; gen_random_uuid() (v4) is used here because the
-- database has no uuidv7 function, and nothing orders practitioners by id -- `position` is the display order.
-- setBusinessModule seeds the same default for businesses that switch the module on after this migration.
INSERT INTO "practitioners" ("id", "business_id", "name", "position")
SELECT gen_random_uuid(), s."business_id", left(b."name", 80), 0
FROM "appointment_settings" s
JOIN "businesses" b ON b."id" = s."business_id";
